const model = createCompiledModel(options, "php-wasm-copied-v1", 32, { refinements: true });
// The plain copied side module carries the same caller-limb Fin walk and Lean guards as native
// packages. Author-checked Subtype constructors and components with callbacks have no PHP-Wasm
// acceptance yet, so they stay refused rather than inferred from native PHP.
const refined = model.exports.filter(item => item.refinements);
const subtype = refined.find(item => [...item.refinements.parameters, item.refinements.result].some(value => value?.kind === "subtype"));
if(subtype) throw Object.assign(new TypeError(`${subtype.name}: checked Subtype refinements are not yet supported by PHP-Wasm packages`), { code: "native-refinements-unsupported", details: { declaration: subtype.name } });
const callback = refined.length ? model.types.find(type => type.kind === "callback") : null;
if(callback) throw Object.assign(new TypeError(`${refined[0].name}: checked Fin refinements cannot share a PHP-Wasm package with callables`), { code: "native-refinements-unsupported", details: { declaration: refined[0].name } });

/**
 * Document checked Fin sites of a plain copied PHP-Wasm package. Packages without
 * a bound document nothing, so their README bytes are unchanged.
 *
 * @param projection - Compiled copied PHP model of the package.
 */
export const phpWasmFinReadme = projection => {
	const types = projection.ir.types;
	const bounds = fn => nativeFinSummary(fn.declaration, fn.parameters.map(parameter => `$${parameter.name}`), types);
	const functions = projection.surface.functions.filter(bounds);
	if(!functions.length) return "";
	const declarations = functions.map(fn => fn.declaration);
	return `\n## Bounded integers\n\n${nativeRefinementReadme(declarations, `Lean Fin n parameters and results are Brick\\Math\\BigInteger values below n. The PHP-Wasm side module compares each argument with its exact bound, including bounds wider than 64 bits, before any Lean code runs; a value at or above its bound throws LeanBridgeError with code 1 whose message names the Lean parameter and bound. Fin 0 has no values, so every call to a function taking one is rejected. Results are BigInteger values below their declared bound. ${nativeFinContainerNote(declarations, "PHP-Wasm packages", types)}`, "PHP-Wasm packages", types)}\n\n${functions.map(fn => `- ${projection.namespace}\\${fn.field}: ${bounds(fn)}`).join("\n")}\n`;
};

// Checked Fin and generic records on PHP-Wasm run after the collection gate, each with its own report.
const phpWasmGates = [["LEAN_BRIDGE_PHP_WASM_FIN_TEST=1 node --test --test-concurrency=1 tests/php-wasm-fin.test.mjs", "build/php-wasm-fin/ordinary.json"]
  , ["LEAN_BRIDGE_PHP_WASM_GENERIC_RECORD_TEST=1 node --test --test-concurrency=1 tests/php-wasm-generic-records.test.mjs", "build/generic-records/php-wasm.json"]];
for(const [command, report] of phpWasmGates)
{
  assert.ok(workflow.includes(`          ${command}\n          test -s ${report}\n`), command);
  assert.ok(workflow.includes(`            ${report}\n`), report);
  assert.ok(workflow.includes(` && ${command} && `), command);
}

